:root {
  color-scheme: light;
  --background: #f6f7fb;
  --background-elevated: #ffffff;
  --surface: #ffffff;
  --surface-muted: #eef2ff;
  --text: #102033;
  --text-muted: #55657a;
  --border: #d7deea;
  --accent: #3155ff;
  --accent-strong: #2440d0;
  --accent-soft: rgba(49, 85, 255, 0.12);
  --success: #0f9d58;
  --warning: #b45309;
  --error: #c53030;
  --shadow: 0 18px 45px rgba(16, 32, 51, 0.08);
  --radius-lg: 24px;
  --radius-md: 16px;
  --radius-sm: 12px;
  --max-width: 1120px;
  --gap: 1.25rem;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    'Segoe UI', sans-serif;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    color-scheme: dark;
    --background: #07111f;
    --background-elevated: #0d1727;
    --surface: #101b2b;
    --surface-muted: #16253c;
    --text: #edf2ff;
    --text-muted: #a4b1c7;
    --border: #22324a;
    --accent: #8ea2ff;
    --accent-strong: #b3c0ff;
    --accent-soft: rgba(142, 162, 255, 0.14);
    --success: #58d68d;
    --warning: #f4b24d;
    --error: #ff7b7b;
    --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
  }
}

:root[data-theme='dark'] {
  color-scheme: dark;
  --background: #07111f;
  --background-elevated: #0d1727;
  --surface: #101b2b;
  --surface-muted: #16253c;
  --text: #edf2ff;
  --text-muted: #a4b1c7;
  --border: #22324a;
  --accent: #8ea2ff;
  --accent-strong: #b3c0ff;
  --accent-soft: rgba(142, 162, 255, 0.14);
  --success: #58d68d;
  --warning: #f4b24d;
  --error: #ff7b7b;
  --shadow: 0 24px 60px rgba(0, 0, 0, 0.35);
}

* {
  box-sizing: border-box;
}

html {
  background: var(--background);
}

body {
  margin: 0;
  min-height: 100vh;
  background: var(--background);
  color: var(--text);
}

a {
  color: inherit;
  text-decoration: none;
}

a:hover {
  color: var(--accent-strong);
}

button,
input,
select {
  font: inherit;
}

button {
  cursor: pointer;
}

.app-shell {
  width: min(var(--max-width), calc(100vw - 2rem));
  margin: 0 auto;
  padding: 2rem 0 4rem;
}

.site-header,
.panel,
.card,
.notice,
.result-meta,
.filter-row,
.result-header,
.detail-header,
.detail-meta,
.segment,
.stat {
  border: 1px solid var(--border);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.site-header {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: end;
  border-radius: var(--radius-lg);
  padding: 1.5rem 1.75rem;
  margin-bottom: 1.5rem;
  background: linear-gradient(135deg, var(--surface), var(--background-elevated));
}

.eyebrow {
  margin: 0 0 0.35rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-size: 0.75rem;
  color: var(--text-muted);
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1 {
  margin-bottom: 0;
  font-size: clamp(1.6rem, 4vw, 2.6rem);
  line-height: 1.1;
}

h2 {
  margin-bottom: 0.85rem;
  font-size: 1.25rem;
}

h3 {
  margin-bottom: 0.5rem;
}

.site-note {
  max-width: 28rem;
  margin-bottom: 0;
  color: var(--text-muted);
}

.panel {
  border-radius: var(--radius-lg);
  padding: 1.25rem;
}

.search-panel {
  display: grid;
  gap: 1rem;
}

.search-form {
  display: grid;
  gap: 0.9rem;
}

.search-input,
.search-select,
.search-button,
.search-textarea {
  border-radius: 14px;
  border: 1px solid var(--border);
  background: var(--background-elevated);
  color: var(--text);
}

.search-input,
.search-select,
.search-textarea {
  padding: 0.8rem 0.95rem;
  width: 100%;
}

.search-textarea {
  min-height: 96px;
  resize: vertical;
}

.search-button {
  padding: 0.9rem 1.2rem;
  font-weight: 700;
  background: var(--accent);
  color: white;
  border-color: transparent;
}

.search-button:disabled {
  opacity: 0.6;
  cursor: wait;
}

.form-grid {
  display: grid;
  gap: 0.8rem;
  grid-template-columns: 1.2fr repeat(4, minmax(0, 1fr));
}

@media (max-width: 900px) {
  .form-grid {
    grid-template-columns: 1fr 1fr;
  }

  .site-header {
    flex-direction: column;
    align-items: start;
  }
}

@media (max-width: 640px) {
  .form-grid {
    grid-template-columns: 1fr;
  }

  .app-shell {
    width: min(var(--max-width), calc(100vw - 1rem));
    padding: 0.75rem 0 3rem;
  }
}

.filter-row {
  display: grid;
  gap: 0.8rem;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-radius: 18px;
  padding: 0.9rem;
}

.helper,
.meta,
.result-snippet,
.detail-copy,
.empty-state,
.error-state,
.loading-state {
  color: var(--text-muted);
}

.notice {
  border-radius: 18px;
  padding: 0.9rem 1rem;
  background: var(--accent-soft);
  color: var(--text);
}

.notice strong {
  color: var(--accent-strong);
}

.segment {
  border-radius: 18px;
  padding: 1rem;
  background: var(--surface-muted);
}

.results {
  display: grid;
  gap: 0.9rem;
}

.card {
  border-radius: 18px;
  padding: 1rem;
  background: var(--surface);
}

.card h3 {
  font-size: 1.05rem;
}

.card-title {
  display: flex;
  gap: 0.6rem;
  justify-content: space-between;
  align-items: start;
}

.badge-row,
.meta-row,
.stat-row,
.pill-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.badge,
.pill,
.stat {
  border-radius: 999px;
  padding: 0.35rem 0.7rem;
  font-size: 0.83rem;
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.badge {
  background: var(--accent-soft);
  color: var(--accent-strong);
  border: 1px solid transparent;
}

.pill {
  background: var(--background-elevated);
  border: 1px solid var(--border);
  color: var(--text-muted);
}

.stat {
  background: var(--background-elevated);
  color: var(--text);
}

.result-header,
.detail-header {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: start;
  border-radius: 18px;
  padding: 1rem 1.1rem;
}

.result-header {
  margin-bottom: 0.8rem;
}

.result-meta,
.detail-meta {
  border-radius: 18px;
  padding: 0.75rem 0.9rem;
}

.link-button {
  color: var(--accent-strong);
  font-weight: 700;
}

.link-button:hover {
  text-decoration: underline;
}

.stack {
  display: grid;
  gap: 0.9rem;
}

.detail-grid {
  display: grid;
  gap: 1rem;
}

.detail-section {
  display: grid;
  gap: 0.65rem;
}

.detail-section p {
  margin-bottom: 0;
}

.muted {
  color: var(--text-muted);
}

.loading-state,
.empty-state,
.error-state {
  padding: 1rem;
  border-radius: 18px;
  background: var(--surface);
  border: 1px dashed var(--border);
}

.small {
  font-size: 0.9rem;
}

'use client';

import { useMemo, useState } from 'react';
import type { SearchFilters, SearchResponse } from '@/pubmed/types';

type SearchPanelProps = {
  initialQuery?: string;
  initialResults?: SearchResponse | null;
};

const defaultFilters: SearchFilters = {
  fromYear: undefined,
  toYear: undefined,
  publicationTypes: undefined,
  journal: undefined,
  language: undefined,
};

export function SearchPanel({
  initialQuery = '',
  initialResults = null,
}: SearchPanelProps) {
  const [query, setQuery] = useState(initialQuery);
  const [fromYear, setFromYear] = useState('');
  const [toYear, setToYear] = useState('');
  const [publicationTypes, setPublicationTypes] = useState('');
  const [journal, setJournal] = useState('');
  const [language, setLanguage] = useState('');
  const [results, setResults] = useState<SearchResponse | null>(initialResults);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const displayResults = results?.results ?? [];
  const total = results?.total ?? 0;
  const hasSearched = Boolean(results || error || query);

  const filters = useMemo<SearchFilters>(() => {
    return {
      fromYear: fromYear ? Number(fromYear) : defaultFilters.fromYear,
      toYear: toYear ? Number(toYear) : defaultFilters.toYear,
      publicationTypes: publicationTypes
        ? publicationTypes.split(',').map((item) => item.trim()).filter(Boolean)
        : defaultFilters.publicationTypes,
      journal: journal.trim() || defaultFilters.journal,
      language: language.trim() || defaultFilters.language,
    };
  }, [fromYear, toYear, publicationTypes, journal, language]);

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setLoading(true);
    setError(null);
    try {
      const searchParams = new URLSearchParams();
      searchParams.set('q', query);
      searchParams.set('page', '1');
      searchParams.set('page_size', '10');
      if (filters.fromYear) {
        searchParams.set('from_year', String(filters.fromYear));
      }
      if (filters.toYear) {
        searchParams.set('to_year', String(filters.toYear));
      }
      if (filters.publicationTypes?.length) {
        searchParams.set('publication_types', filters.publicationTypes.join(','));
      }
      if (filters.journal) {
        searchParams.set('journal', filters.journal);
      }
      if (filters.language) {
        searchParams.set('language', filters.language);
      }

      const response = await fetch(`/api/search?${searchParams.toString()}`);
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data?.error?.message || 'Search failed.');
      }
      setResults(data as SearchResponse);
    } catch (submitError) {
      setResults(null);
      setError(
        submitError instanceof Error
          ? submitError.message
          : 'The search request could not be completed.',
      );
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="search-panel panel">
      <div className="notice">
        <strong>Purpose:</strong> literature discovery over PubMed abstracts. Use the
        fixture corpus by default; switch to live E-utilities with environment
        variables when needed.
      </div>

      <form className="search-form" onSubmit={handleSubmit}>
        <label className="stack">
          <span>Search query</span>
          <textarea
            className="search-textarea"
            placeholder="e.g. biologics for asthma review"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
          />
        </label>

        <div className="filter-row">
          <label className="stack">
            <span>From year</span>
            <input
              className="search-input"
              inputMode="numeric"
              placeholder="2018"
              value={fromYear}
              onChange={(event) => setFromYear(event.target.value)}
            />
          </label>
          <label className="stack">
            <span>To year</span>
            <input
              className="search-input"
              inputMode="numeric"
              placeholder="2026"
              value={toYear}
              onChange={(event) => setToYear(event.target.value)}
            />
          </label>
          <label className="stack">
            <span>Publication types</span>
            <input
              className="search-input"
              placeholder="Review, Randomized Controlled Trial"
              value={publicationTypes}
              onChange={(event) => setPublicationTypes(event.target.value)}
            />
          </label>
          <label className="stack">
            <span>Journal</span>
            <input
              className="search-input"
              placeholder="Journal of Clinical Medicine"
              value={journal}
              onChange={(event) => setJournal(event.target.value)}
            />
          </label>
          <label className="stack">
            <span>Language</span>
            <input
              className="search-input"
              placeholder="eng"
              value={language}
              onChange={(event) => setLanguage(event.target.value)}
            />
          </label>
        </div>

        <button className="search-button" disabled={loading} type="submit">
          {loading ? 'Searching PubMed…' : 'Search'}
        </button>
      </form>

      {error ? (
        <div className="error-state">
          <strong>Upstream error:</strong> {error}
        </div>
      ) : null}

      {!hasSearched ? (
        <div className="empty-state">
          Enter a query to search the current corpus. Results will show PMID,
          title, authors, journal, publication date, publication type, abstract
          excerpt, and PubMed link.
        </div>
      ) : null}

      {results ? (
        <div className="stack">
          <div className="result-header">
            <div>
              <h2>Ranked results</h2>
              <p className="helper">
                {total} records matched on the selected corpus
              </p>
            </div>
            <div className="badge-row">
              <span className="badge">Source: {results.source}</span>
              {filters.fromYear ? <span className="pill">from {filters.fromYear}</span> : null}
              {filters.toYear ? <span className="pill">to {filters.toYear}</span> : null}
            </div>
          </div>

          {displayResults.length === 0 ? (
            <div className="empty-state">
              No results matched. Try a broader query, fewer filters, or a different
              synonym.
            </div>
          ) : (
            <div className="results">
              {displayResults.map((article) => (
                <article className="card" key={article.pmid}>
                  <div className="card-title">
                    <div>
                      <h3>{article.title}</h3>
                      <p className="meta">PMID {article.pmid}</p>
                    </div>
                    <span className="stat">Score {article.score.toFixed(2)}</span>
                  </div>
                  <div className="badge-row">
                    {article.publicationTypes.slice(0, 3).map((type) => (
                      <span className="badge" key={type}>
                        {type}
                      </span>
                    ))}
                    {article.retracted ? <span className="badge">Retracted</span> : null}
                    {article.corrected ? <span className="badge">Corrected</span> : null}
                  </div>
                  <div className="meta-row">
                    <span className="pill">
                      {article.authors.slice(0, 3).join(', ')}
                      {article.authors.length > 3 ? ' et al.' : ''}
                    </span>
                    <span className="pill">{article.journal}</span>
                    <span className="pill">{article.publicationDate}</span>
                    {article.doi ? <span className="pill">DOI {article.doi}</span> : null}
                  </div>
                  <p className="result-snippet">{article.abstractExcerpt}</p>
                  <div className="meta-row">
                    <a className="link-button" href={article.pubmedUrl} rel="noreferrer" target="_blank">
                      View on PubMed
                    </a>
                    <a className="link-button" href={`/articles/${article.pmid}`}>
                      Open detail view
                    </a>
                  </div>
                </article>
              ))}
            </div>
          )}
        </div>
      ) : null}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';
import type { Article } from '@/pubmed/types';

type ArticleDetailProps = {
  pmid: string;
};

type DetailState =
  | { status: 'loading' }
  | { status: 'empty' }
  | { status: 'error'; message: string }
  | { status: 'ready'; article: Article };

export function ArticleDetail({ pmid }: ArticleDetailProps) {
  const [state, setState] = useState<DetailState>({ status: 'loading' });

  useEffect(() => {
    let active = true;

    async function load() {
      setState({ status: 'loading' });
      try {
        const response = await fetch(`/api/articles/${pmid}`);
        const data = await response.json();
        if (!response.ok) {
          throw new Error(data?.error?.message || 'Article lookup failed.');
        }
        if (!data.article) {
          if (active) {
            setState({ status: 'empty' });
          }
          return;
        }
        if (active) {
          setState({ status: 'ready', article: data.article as Article });
        }
      } catch (error) {
        if (active) {
          setState({
            status: 'error',
            message:
              error instanceof Error
                ? error.message
                : 'The article could not be loaded.',
          });
        }
      }
    }

    void load();

    return () => {
      active = false;
    };
  }, [pmid]);

  if (state.status === 'loading') {
    return <div className="loading-state">Loading article detail…</div>;
  }

  if (state.status === 'error') {
    return (
      <div className="error-state">
        <strong>Upstream error:</strong> {state.message}
      </div>
    );
  }

  if (state.status === 'empty') {
    return (
      <div className="empty-state">
        No article was found for PMID {pmid}.
      </div>
    );
  }

  const { article } = state;

  return (
    <article className="detail-grid panel">
      <div className="detail-header">
        <div>
          <p className="eyebrow">PMID {article.pmid}</p>
          <h2>{article.title}</h2>
          <p className="detail-copy">
            {article.authors.slice(0, 5).join(', ')}
            {article.authors.length > 5 ? ' et al.' : ''}
          </p>
        </div>
        <div className="badge-row">
          <span className="badge">{article.journal}</span>
          <span className="stat">{article.publicationDate}</span>
        </div>
      </div>

      <div className="detail-meta">
        <div className="pill-row">
          {article.publicationTypes.length ? (
            article.publicationTypes.map((type) => (
              <span className="pill" key={type}>
                {type}
              </span>
            ))
          ) : (
            <span className="pill">Publication type unavailable</span>
          )}
          <span className="pill">Language: {article.language}</span>
          {article.doi ? <span className="pill">DOI {article.doi}</span> : null}
          {article.retracted ? <span className="pill">Retracted</span> : null}
          {article.corrected ? <span className="pill">Corrected</span> : null}
        </div>
      </div>

      <section className="detail-section">
        <h3>Abstract excerpt</h3>
        <p>{article.abstractExcerpt}</p>
        <p className="muted small">Full abstract text is shown below when available.</p>
        {article.abstractText ? <p>{article.abstractText}</p> : <p>No abstract text available.</p>}
      </section>

      <section className="detail-section">
        <h3>Metadata</h3>
        <div className="meta-row">
          <a className="link-button" href={article.pubmedUrl} rel="noreferrer" target="_blank">
            View on PubMed
          </a>
        </div>
      </section>
    </article>
  );
}

import { SearchPanel } from '@/components/search-panel';

export default function HomePage() {
  return <SearchPanel />;
}

import { ArticleDetail } from '@/components/article-detail';

export default async function ArticlePage({
  params,
}: {
  params: Promise<{ pmid: string }>;
}) {
  const { pmid } = await params;
  return <ArticleDetail pmid={pmid} />;
}

export default function Loading() {
  return <div className="loading-state panel">Loading PubMedChat…</div>;
}

export default function Loading() {
  return <div className="loading-state panel">Loading article detail…</div>;
}

