2	import { useEffect, useState } from 'react';
3	import type { Article } from '@/pubmed/types';
4	
5	type ArticleDetailProps = {
6	  pmid: string;
7	};
8	
9	type DetailState =
10	  | { status: 'loading' }
11	  | { status: 'empty' }
12	  | { status: 'error'; message: string }
13	  | { status: 'ready'; article: Article };
14	
15	export function ArticleDetail({ pmid }: ArticleDetailProps) {
16	  const [state, setState] = useState<DetailState>({ status: 'loading' });
17	
18	  useEffect(() => {
19	    let active = true;
20	
21	    async function load() {
22	      setState({ status: 'loading' });
23	      try {
24	        const response = await fetch(`/api/articles/${pmid}`);
25	        const data = await response.json();
26	        if (!response.ok) {
27	          throw new Error(data?.error?.message || 'Article lookup failed.');
28	        }
29	        if (!data.article) {
30	          if (active) {
31	            setState({ status: 'empty' });
32	          }
33	          return;
34	        }
35	        if (active) {
36	          setState({ status: 'ready', article: data.article as Article });
37	        }
38	      } catch (error) {
39	        if (active) {
40	          setState({
41	            status: 'error',
