python3 - <<'PY'
from pathlib import Path
root = Path('/home/ivantang-vbox/repos/PubMedChat')
skip_dirs = {'node_modules', '.next', '.omc', '.claude'}
patterns = ['api_key=', 'llm_api_key=', 'pubmed_api_key=', 'secret=', 'password=', 'token=', 'bearer ', 'sk-', 'AKIA']
matches = []
for path in root.rglob('*'):
    if any(part in skip_dirs for part in path.parts):
        continue
    if not path.is_file():
        continue
    if path.suffix in {'.png', '.jpg', '.jpeg', '.gif', '.ico'}:
        continue
    try:
        text = path.read_text(encoding='utf-8')
    except UnicodeDecodeError:
        continue
    lower = text.lower()
    for pattern in patterns:
        if pattern.lower() in lower:
            matches.append((str(path.relative_to(root)), pattern))
            break
if matches:
    for rel, pattern in matches:
        print(f'{rel}: matched {pattern}')
else:
    print('No obvious secret patterns found outside ignored/generated directories.')
PY

